import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
import axios from "@/utils/axios";
import * as imageConversion from "image-conversion";
import uploadConfig from "@/views/client/mixins/uploadConfig";
import { fetchFileFromUrl, uploadFile, cleanChunkedUpload } from "@/utils/api";
export default {
  name: "UploadForm",
  mixins: [uploadConfig],
  data() {
    return {
      fileList: [],
      // 上传的文件列表
      maxUploading: 6,
      // 最大同时上传数
      waitingList: [],
      // 等待上传的文件列表
      exceptionList: [],
      // 上传失败的文件列表
      listScrolled: false,
      // 列表是否滚动
      pastedUrls: "",
      // 粘贴的外链文本
      pasteUploadMethod: "save",
      chunk_threshold: 20 * 1024 * 1024,
      // 文件块阈值，超过该值则使用分块上传，20MB
      chunk_size: 10 * 1024 * 1024 // 分块大小，10MB
    };
  },
  computed: {
    isMobile() {
      return window.innerWidth <= 768;
    },
    uploadSuccessCount() {
      return this.fileList.filter(item => item.status === "success" || item.status === "done").length;
    },
    uploadErrorCount() {
      return this.fileList.filter(item => item.status === "exception").length;
    },
    uploadingCount() {
      return this.fileList.filter(item => item.status === "uploading").length;
    },
    waitingCount() {
      return this.waitingList.length;
    },
    uploading() {
      return this.fileList.some(item => item.status === "uploading" || item.status === "waiting");
    },
    rootUrl() {
      return this.useCustomUrl ? this.customUrlPrefix : this.urlPrefix;
    }
  },
  watch: {
    useCustomUrl() {
      if (this.useCustomUrl) {
        this.fileList.forEach(item => {
          if (item.uploadChannel !== "external") {
            item.finalURL = this.customUrlPrefix + item.srcID;
            item.mdURL = `![${item.name}](${this.customUrlPrefix + item.srcID})`;
            item.htmlURL = `<img src="${this.customUrlPrefix + item.srcID}" alt="${item.name}" width=100% />`;
            item.ubbURL = `[img]${this.customUrlPrefix + item.srcID}[/img]`;
          }
        });
      } else {
        this.fileList.forEach(item => {
          if (item.uploadChannel !== "external") {
            item.finalURL = this.rootUrl + item.srcID;
            item.mdURL = `![${item.name}](${this.rootUrl + item.srcID})`;
            item.htmlURL = `<img src="${this.rootUrl + item.srcID}" alt="${item.name}" width=100% />`;
            item.ubbURL = `[img]${this.rootUrl + item.srcID}[/img]`;
          }
        });
      }
    },
    customUrlPrefix() {
      if (this.useCustomUrl) {
        this.fileList.forEach(item => {
          if (item.uploadChannel !== "external") {
            item.finalURL = this.customUrlPrefix + item.srcID;
            item.mdURL = `![${item.name}](${this.customUrlPrefix + item.srcID})`;
            item.htmlURL = `<img src="${this.customUrlPrefix + item.srcID}" alt="${item.name}" width=100% />`;
            item.ubbURL = `[img]${this.customUrlPrefix + item.srcID}[/img]`;
          }
        });
      }
    }
  },
  methods: {
    // 鼠标移动光晕跟随
    handleCardMouseMove(e) {
      const card = e.currentTarget;
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      card.style.setProperty("--mouse-x", `${x}px`);
      card.style.setProperty("--mouse-y", `${y}px`);
    },
    // 点击波纹扩散
    handleCardRipple(e) {
      const card = e.currentTarget;
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      // 生成 2 个波纹，设置不同的延迟，形成多层扩散效果
      [0, 300].forEach(delay => {
        const ripple = document.createElement("span");
        ripple.className = "click-ripple";
        const initialSize = 10;
        ripple.style.width = ripple.style.height = `${initialSize}px`;
        ripple.style.left = `${x - initialSize / 2}px`;
        ripple.style.top = `${y - initialSize / 2}px`;
        ripple.style.animationDelay = `${delay}ms`;
        card.appendChild(ripple);
        setTimeout(() => {
          ripple.remove();
        }, 1500 + delay);
      });
    },
    // 切换上传方式
    switchUploadMethod() {
      this.uploadMethod = this.uploadMethod === "default" ? "paste" : "default";
    },
    // 文件上传前的检查和处理
    beforeUpload(file) {
      return new Promise(async (resolve, reject) => {
        // 1. 类型检查
        if (!this.isImage(file.name)) {
          this.$message.error(`${file.name} 不是图片文件类型!`);
          return reject(false);
        }

        // 2. 文件大小限制（Telegram 2GB）
        if (file.size / 1024 / 1024 > 1024 && this.uploadChannel === "telegram" && !this.useClientCompress) {
          this.$message.error(`${file.name} 文件超过 2GB!`);
          return reject(false);
        }

        // 3. 客户端压缩
        let processedFile = file;
        if (this.useClientCompress && file.size / 1024 / 1024 > this.clientCompressBar) {
          try {
            const compressed = await imageConversion.compressAccurately(file, 1024 * this.clientCompressQuality);
            if (compressed.size / 1024 / 1024 > 1024 && this.uploadChannel === "telegram") {
              this.$message.error(`${file.name} 压缩后文件过大!`);
              return reject(false);
            }
            processedFile = new File([compressed], file.name, {
              type: compressed.type
            });
            processedFile.uid = file.uid;
          } catch (err) {
            this.$message.error(`${file.name} 压缩失败!`);
            return reject(false);
          }
        }

        // 4. 添加到文件列表
        this.fileList.push({
          uid: processedFile.uid,
          name: processedFile.name,
          url: URL.createObjectURL(processedFile),
          finalURL: "",
          mdURL: "",
          htmlURL: "",
          ubbURL: "",
          srcID: "",
          status: "uploading",
          progress: 0
        });
        resolve(processedFile);
      });
    },
    // 上传文件入口函数
    uploadFile(option) {
      const fileItem = this.fileList.find(item => item.uid === option.file.uid);
      if (!fileItem) return;
      if (this.uploadingCount >= this.maxUploading) {
        this.waitingList.push(option);
        fileItem.status = "waiting";
        return;
      }
      fileItem.status = "uploading";
      const uploadChannel = fileItem.uploadChannel || this.uploadChannel;

      // 如果上传渠道为外链，直接使用外链上传
      if (uploadChannel === "external") {
        this.uploadSingleFile(option);
      }
      // 其他渠道，检查文件大小，决定是否使用分块上传
      else if (option.file.size > this.chunk_threshold) {
        this.uploadFileInChunks(option);
      } else {
        this.uploadSingleFile(option);
      }
      // 滚动到顶部
      this.$nextTick(() => {
        setTimeout(() => {
          if (this.$refs.scrollContainer) {
            this.$refs.scrollContainer.scrollTo({
              top: 0,
              behavior: "smooth"
            });
          }
        }, 100);
      });
    },
    // 单文件上传
    uploadSingleFile(option) {
      const fileItem = this.fileList.find(item => item.uid === option.file.uid);
      // 上传参数
      const uploadParams = {
        uploadChannel: fileItem.uploadChannel || this.uploadChannel,
        uploadNameType: this.uploadNameType,
        autoRetry: this.uploadRetry && fileItem.uploadChannel !== "external",
        uploadFolder: this.uploadFolder
      };
      // 文件数据
      const formData = new FormData();
      formData.append("file", option.file);
      if (fileItem.uploadChannel === "external") {
        formData.append("url", option.file.url);
      }
      // 上传进度回调函数
      const onUploadProgress = event => {
        const percentCompleted = Math.round(event.loaded / event.total * 100);
        option.onProgress({
          percent: percentCompleted,
          file: option.file
        });
      };
      uploadFile({
        uploadParams,
        formData,
        onUploadProgress
      }).then(res => {
        option.onSuccess(res, option.file);
      }).catch(err => {
        if (err.response && err.response.status !== 401) {
          this.exceptionList.push(option.file);
          option.onError(err, option.file);
        }
      });
    },
    // 分块上传
    async uploadFileInChunks(option) {
      const fileItem = this.fileList.find(item => item.uid === option.file.uid);
      const fileSize = option.file.size;
      const totalChunks = Math.ceil(fileSize / this.chunk_size);
      let uploadParams = {};
      let formData = {};
      try {
        // 第一步：初始化分块上传，获取uploadId
        uploadParams = {
          uploadChannel: fileItem.uploadChannel || this.uploadChannel,
          uploadNameType: this.uploadNameType,
          autoRetry: this.uploadRetry && fileItem.uploadChannel !== "external",
          uploadFolder: this.uploadFolder,
          initChunked: true
        };
        formData = new FormData();
        formData.append("originalFileName", option.file.name);
        formData.append("originalFileType", option.file.type);
        formData.append("totalChunks", totalChunks.toString());
        const initResponse = await uploadFile(uploadParams, formData);
        if (!initResponse.data.success) {
          throw new Error("初始化分块上传失败: " + initResponse.data.message);
        }
        const uploadId = initResponse.data.uploadId;
        console.log("分块上传初始化成功，uploadId:", uploadId);

        // 记录 totalChunks 和 uploadId
        if (fileItem) {
          fileItem.totalChunks = totalChunks;
          fileItem.uploadId = uploadId;
        }

        // 第二步：上传所有分块
        for (let i = 0; i < totalChunks; i++) {
          const start = i * this.chunk_size;
          const end = Math.min(start + this.chunk_size, fileSize);
          const chunk = option.file.slice(start, end);
          uploadParams = {
            uploadChannel: fileItem.uploadChannel || this.uploadChannel,
            uploadNameType: this.uploadNameType,
            autoRetry: this.uploadRetry && fileItem.uploadChannel !== "external",
            uploadFolder: this.uploadFolder,
            chunked: true
          };
          formData = new FormData();
          formData.append("file", chunk, `${option.file.name}.part${i.toString().padStart(3, "0")}`);
          formData.append("chunkIndex", i.toString());
          formData.append("totalChunks", totalChunks.toString());
          formData.append("uploadId", uploadId);
          formData.append("originalFileName", option.file.name);
          formData.append("originalFileType", option.file.type);
          const onUploadProgress = progressEvent => {
            const chunkProgress = Math.round(progressEvent.loaded / progressEvent.total * 100);
            const totalProgress = Math.round((i * 100 + chunkProgress) / totalChunks);
            option.onProgress({
              percent: totalProgress,
              file: option.file
            });
          };
          let retryCount = 0;
          const maxRetries = 3;
          while (retryCount < maxRetries) {
            try {
              await uploadFile({
                uploadParams,
                formData,
                onUploadProgress
              });
              break; // 成功，跳出重试循环
            } catch (err) {
              retryCount++;
              if (retryCount >= maxRetries) {
                throw new Error(`分块 ${i + 1}/${totalChunks} 上传失败: ${err.message}`);
              }
              // 等待后重试
              await new Promise(resolve => setTimeout(resolve, 1000 * retryCount));
            }
          }
          if (retryCount === maxRetries) {
            throw new Error(`分块 ${i + 1}/${totalChunks} 上传失败，已重试 ${maxRetries} 次`);
          }
        }

        // 第三步：所有分块上传完成，发送合并请求
        uploadParams = {
          uploadChannel: fileItem.uploadChannel || this.uploadChannel,
          uploadNameType: this.uploadNameType,
          autoRetry: this.uploadRetry && fileItem.uploadChannel !== "external",
          uploadFolder: this.uploadFolder,
          chunked: true,
          merge: true
        };
        formData = new FormData();
        formData.append("uploadId", uploadId);
        formData.append("totalChunks", totalChunks.toString());
        formData.append("originalFileName", option.file.name);
        formData.append("originalFileType", option.file.type);
        const response = await uploadFile({
          uploadParams,
          formData
        });
        // 检查是否为异步处理
        if (response.status === 202) {
          // 异步处理，开始轮询状态
          await this.pollMergeStatus(response.data.uploadId, response.data.statusCheckUrl, option);
        } else {
          // 同步处理完成
          option.onSuccess(response, option.file);
        }
      } catch (err) {
        console.error("分块上传失败:", err);

        // 如果有uploadId，清理相关资源
        const fileItem = this.fileList.find(item => item.uid === option.file.uid);
        if (fileItem && fileItem.uploadId) {
          cleanChunkedUpload({
            uploadId: fileItem.uploadId,
            totalChunks: fileItem.totalChunks
          }).then(() => {
            console.log(`已清理分块上传失败的资源: ${fileItem.uploadId}`);
          }).catch(cleanupError => {
            console.warn("清理分块上传失败资源时出错:", cleanupError);
          });
        }
        if (err.response && err.response.status !== 401) {
          this.exceptionList.push(option.file);
          option.onError(err, option.file);
        }
      }
    },
    // 轮询合并状态
    async pollMergeStatus(uploadId, statusCheckUrl, option) {
      const maxPollingTime = 10 * 60 * 1000; // 10分钟最大轮询时间
      const pollInterval = 2000; // 2秒轮询间隔
      const startTime = Date.now();

      // 显示异步处理提示
      const fileItem = this.fileList.find(item => item.uid === option.file.uid);
      this.$message({
        type: "info",
        message: `${option.file.name} 文件较大，正在后台处理中...`,
        duration: 5000
      });
      const poll = async () => {
        try {
          // 检查是否超时
          if (Date.now() - startTime > maxPollingTime) {
            throw new Error("合并处理超时，请稍后刷新页面查看结果");
          }
          const response = await axios({
            url: statusCheckUrl,
            method: "get",
            withAuthCode: true
          });
          const status = response.data;
          switch (status.status) {
            case "processing":
            case "merging":
            case "uploading":
              // 继续轮询
              setTimeout(poll, pollInterval);
              break;
            case "success":
              // 处理成功
              if (status.result) {
                const mockResponse = {
                  data: status.result,
                  status: 200
                };
                option.onSuccess(mockResponse, option.file);
              } else {
                throw new Error("处理完成但未返回结果");
              }
              break;
            case "error":
              throw new Error(status.message || status.error || "后台处理失败");
            default:
              // 继续轮询
              setTimeout(poll, pollInterval);
          }
        } catch (error) {
          console.error("轮询状态失败:", error);

          // 检查是否为网络错误，如果是则继续重试
          if (error.code === "NETWORK_ERROR" || error.message.includes("Network Error")) {
            if (Date.now() - startTime < maxPollingTime) {
              setTimeout(poll, pollInterval * 2); // 网络错误时延长轮询间隔
              return;
            }
          }

          // 处理失败
          console.error("轮询处理失败:", error);

          // 发送清理请求以清理后台资源
          if (fileItem && fileItem.uploadId) {
            cleanChunkedUpload({
              uploadId: fileItem.uploadId,
              totalChunks: fileItem.totalChunks
            }).then(() => {
              console.log(`已清理失败上传的资源: ${fileItem.uploadId}`);
            }).catch(cleanupError => {
              console.warn("清理失败上传资源时出错:", cleanupError);
            });
          }
          this.$message.error(`${option.file.name} 后台处理失败: ${error.message}`);
          if (fileItem) {
            fileItem.status = "exception";
          }
          this.exceptionList.push(option.file);
          option.onError(error, option.file);
        }
      };

      // 开始轮询
      setTimeout(poll, pollInterval);
    },
    // 文件上传成功
    handleSuccess(response, file) {
      const fileItem = this.fileList.find(item => item.uid === file.uid);
      try {
        const uploadChannel = fileItem.uploadChannel || this.uploadChannel;
        if (uploadChannel !== "external") {
          const srcID = response.data[0].src.replace("/file/", ""); // 去除 response 的 /file/ 前缀
          fileItem.url = `${window.location.protocol}//${window.location.host}/file/` + srcID;
          fileItem.finalURL = this.rootUrl + srcID;
          fileItem.mdURL = `![${file.name}](${this.rootUrl + srcID})`;
          fileItem.htmlURL = `<img src="${this.rootUrl + srcID}" alt="${file.name}" width=100% />`;
          fileItem.ubbURL = `[img]${this.rootUrl + srcID}[/img]`;
          fileItem.srcID = srcID;
        }
        fileItem.progress = 100;
        fileItem.status = "success";
        this.$message.success(file.name + "上传成功");
        setTimeout(() => {
          fileItem.status = "done";
        }, 500);
      } catch (error) {
        this.$message.error(file.name + "上传失败");
        fileItem.status = "exception";
      } finally {
        if (this.waitingList.length) {
          // 上传下一个等待的文件
          const option = this.waitingList.shift();
          this.uploadFile(option);
        }
      }
    },
    // 文件上传失败
    handleError(err, file) {
      this.$message.error(file.name + "上传失败");
      this.fileList.find(item => item.uid === file.uid).status = "exception";
      if (this.waitingList.length) {
        const option = this.waitingList.shift();
        this.uploadFile(option);
      }
    },
    // 处理文件上传进度
    handleProgress({
      percent,
      file
    }) {
      this.fileList.find(item => item.uid === file.uid).progress = percent;
    },
    // 清空文件列表
    clearFileList() {
      if (this.fileList.length > 0) {
        this.fileList = [];
        this.$message.success("文件列表已清空");
      }
    },
    // 清空已成功上传的文件
    clearSuccessList() {
      if (this.uploadSuccessCount > 0) {
        this.fileList = this.fileList.filter(item => item.status !== "success" || item.status !== "done");
        this.$message.success("已清空成功上传的文件");
      }
    },
    // 处理外链字符串上传
    uploadFromUrl(text) {
      const urlPattern = /^(https?:\/\/[^\s$.?#].[^\s]*)$/;
      let fileName = "";
      if (urlPattern.test(text)) {
        fetchFileFromUrl({
          fileUrl: text
        }).then(response => {
          const contentType = response.headers["content-type"];
          if (response.status == 200 && contentType.includes("image")) {
            // 提取文件名
            const disposition = response.headers["content-disposition"];
            if (disposition) {
              const filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
              const filenameStarRegex = /filename\*\s*=\s*UTF-8''([^;\n]*)/; // 处理 filename*
              const matchFilename = filenameRegex.exec(disposition);
              const matchFilenameStar = filenameStarRegex.exec(disposition);
              const rawName = matchFilename?.[1]?.replace(/['"]/g, "") || matchFilenameStar?.[1] || "";
              if (rawName) {
                try {
                  fileName = decodeURIComponent(rawName);
                } catch {
                  fileName = "";
                }
              }
            }
            // 未提取到文件名，尝试从URL中提取文件名
            if (fileName === "") {
              const url = new URL(text);
              if (this.isImage(url.pathname)) {
                // url包含合法的图片后缀
                fileName = url.pathname.split("/").pop();
              } else {
                // url不包含合法的图片后缀，使用默认文件名
                fileName = "PastedFile" + Date.now() + ".jpeg"; // 默认文件名
                this.$message.warning("未能从URL中提取到有效的图片文件名，已使用默认文件名");
              }
            }

            // 读取文件内容
            const blob = response.data;
            const file = new File([blob], fileName, {
              type: blob.type
            });
            file.uid = crypto.randomUUID();

            // 接收beforeUpload的Promise对象
            this.beforeUpload(file).then(newFile => {
              if (newFile instanceof File) {
                this.uploadFile({
                  file: newFile,
                  onProgress: event => this.handleProgress(event),
                  onSuccess: (response, file) => this.handleSuccess(response, file),
                  onError: (error, file) => this.handleError(error, file)
                });
              }
            }).catch(err => {
              console.log(err);
            });
          }
        }).catch(error => {
          this.$message.error("URL地址 " + text + " 无效或不是图片格式");
        });
      } else {
        this.$message.warning(text + " 不是有效的URL地址");
      }
    },
    // 处理文本域中粘贴的外链上传
    uploadPasteUrls() {
      const urls = this.pastedUrls.split("\n");
      const validUrls = urls.map(url => url.trim()).filter(url => url !== "").filter(url => /^(https?:\/\/[^\s$.?#].[^\s]*)$/.test(url));

      // 根据粘贴上传方式进行上传
      if (this.pasteUploadMethod === "save") {
        // 获取外链内容并上传文件
        for (let validUrl of validUrls) {
          this.uploadFromUrl(validUrl);
        }
      } else if (this.pasteUploadMethod === "external") {
        // 仅保存外链，使用 external 渠道上传
        for (let i = 0; i < validUrls.length; i++) {
          const url = validUrls[i];
          const fileName = url.split("/").pop();
          const mdUrl = `![${fileName}](${url})`;
          const htmlUrl = `<img src="${url}" alt="${fileName}" width=100% />`;
          const ubbUrl = `[img]${url}[/img]`;
          const file = new File([], url.split("/").pop(), {
            type: "text/plain"
          });
          file.uid = Date.now() + i;
          file.url = url;
          this.fileList.push({
            uid: file.uid,
            name: file.name,
            url: url,
            finalURL: url,
            mdURL: mdUrl,
            htmlURL: htmlUrl,
            ubbURL: ubbUrl,
            srcID: url,
            status: "uploading",
            progress: 0,
            uploadChannel: "external"
          });
          this.uploadFile({
            file: file,
            onProgress: event => this.handleProgress(event),
            onSuccess: (response, file) => this.handleSuccess(response, file),
            onError: (error, file) => this.handleError(error, file)
          });
        }
      }
    },
    // 粘贴事件处理
    handlePaste(event) {
      // 当粘贴位置是文本框时，不执行该操作
      const active = document.activeElement;
      if (active.tagName === "INPUT" || active.tagName === "TEXTAREA") return;
      const items = event.clipboardData.items;
      for (let item of items) {
        if (item.kind === "file") {
          // 处理文件类型的粘贴
          const file = item.getAsFile();
          if (this.isImage(file.name)) {
            file.uid = crypto.randomUUID();
            this.beforeUpload(file).then(newFile => {
              if (newFile instanceof File) {
                this.uploadFile({
                  file: newFile,
                  onProgress: event => this.handleProgress(event),
                  onSuccess: (response, file) => this.handleSuccess(response, file),
                  onError: (error, file) => this.handleError(error, file)
                });
              }
            }).catch(err => {
              console.log(err);
            });
          } else {
            this.$message.error(`${file.name} 不是图片文件类型!`);
          }
        } else if (item.kind === "string") {
          // 处理文本类型的粘贴
          item.getAsString(text => {
            this.uploadFromUrl(text);
          });
        }
      }
    },
    // 复制全部上传成功的文件链接
    copyAllFileLink() {
      const urls = this.fileList.map(item => {
        if (item.status === "success" || item.status === "done") {
          return this.fileForm === "url" ? item.finalURL : this.fileForm === "md" ? item.mdURL : this.fileForm === "html" ? item.htmlURL : this.fileForm === "ubb" ? item.ubbURL : item.finalURL;
        }
      }).join("\n");
      navigator.clipboard.writeText(urls);
      this.$message.success("已复制全部链接");
    },
    // 删除指定文件
    removeSelectFile(file) {
      this.fileList = this.fileList.filter(item => item.uid !== file.uid);
      this.$message({
        type: "info",
        message: file.name + "已删除"
      });
    },
    // 复制指定文件链接到剪贴板
    copySelectFileLink(file, form = this.fileForm) {
      const status = this.fileList.find(item => item.uid === file.uid).status;
      if (status !== "success" && status !== "done") {
        this.$message({
          type: "warning",
          message: "请等待文件上传完成"
        });
        return;
      }
      const clipboardText = form === "url" ? file.finalURL : form === "md" ? file.mdURL : form === "html" ? file.htmlURL : form === "ubb" ? file.ubbURL : file.finalURL;
      navigator.clipboard.writeText(clipboardText).then(() => {
        this.$message.success("已复制到剪贴板");
      }).catch(() => {
        this.$message.error("复制失败");
      });
    },
    // 判断是否为图片类型
    isImage(fileName) {
      const imageExtensions = ["jpg", "jpeg", "png", "gif", "bmp", "webp", "svg", "tiff", "ico", "avif", "heic", "jfif", "pjpeg", "pjp", "raw", "cr2", "nef", "dng", "eps", "ai", "emf", "wmf"];
      const extension = fileName.split(".").pop().toLowerCase();
      return imageExtensions.includes(extension);
    },
    // 判断是否为视频类型
    isVideo(fileName) {
      const videoExtensions = ["mp4", "webm", "ogg", "mkv"];
      const extension = fileName.split(".").pop().toLowerCase();
      return videoExtensions.includes(extension);
    },
    // 滚动事件
    handleScroll(event) {
      this.listScrolled = event.scrollTop > 0 && this.fileList.length > 0;
    },
    // 重试上传失败的文件
    retryError() {
      if (this.exceptionList.length > 0) {
        this.exceptionList.forEach(file => {
          this.uploadFile({
            file: file,
            onProgress: event => this.handleProgress(event),
            onSuccess: (response, file) => this.handleSuccess(response, file),
            onError: (error, file) => this.handleError(error, file)
          });
        });
        this.exceptionList = [];
      } else {
        this.$message.info("无上传失败文件");
      }
    }
  },
  mounted() {
    document.addEventListener("paste", this.handlePaste);
  },
  beforeUnmount() {
    document.removeEventListener("paste", this.handlePaste);
    // 清理状态
    this.waitingList = [];
    this.fileList = [];
  }
};