import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import cookies from "vue-cookies";
import { mapGetters } from "vuex";
import UploadForm from "@/views/client/UploadForm.vue";
import Footer from "@/components/Footer.vue";
import ToggleDark from "@/components/ToggleDark.vue";
import Logo from "@/components/Logo.vue";
import backgroundManager from "@/mixins/backgroundManager";
import UploadSetting from "@/views/client/UploadSetting.vue";
import UserGuide from "@/views/client/UserGuide.vue";
import Announcement from "@/views/client/Announcement.vue";
export default {
  name: "UploadHome",
  mixins: [backgroundManager],
  components: {
    UploadForm,
    UploadSetting,
    UserGuide,
    Announcement,
    Footer,
    ToggleDark,
    Logo
  },
  data() {
    return {
      isToolBarOpen: false,
      //是否打开工具栏
      isFolderInputActive: false,
      showAnnouncementDialog: false,
      // 控制公告弹窗的显示
      announcementContent: "",
      // 公告内容
      showSetting: false,
      // 控制上传设置弹窗的显示
      showGuide: false // 控制用户手册弹窗的显示
    };
  },
  watch: {
    uploadFolder(val) {
      // 验证上传文件夹路径的合法性
      if (this.validateUploadFolder(val)) {
        this.$store.commit("client/setUploadFolder", val);
      } else {
        this.$nextTick(() => {
          this.uploadFolder = this.storeUploadFolder;
        });
      }
    }
  },
  computed: {
    ...mapGetters("base", ["storeUserConfig"]),
    // 上传目录
    uploadFolder: {
      get() {
        return this.$store.getters["client/storeUploadFolder"] || "";
      },
      set(value) {
        if (this.validateUploadFolder(value)) {
          this.$store.commit("client/setUploadFolder", value);
        }
      }
    },
    ownerName() {
      return this.storeUserConfig?.ownerName || "穷拾";
    },
    dialogWidth() {
      return window.innerWidth > 768 ? "50%" : "85%";
    },
    disableTooltip() {
      return window.innerWidth < 768;
    },
    isMobile() {
      return window.innerWidth < 768;
    }
  },
  mounted() {
    // 初始化背景图，启用自动创建元素
    this.initializeBackground("uploadBkImg", ".container", true);
    // 初始化上传目录
    this.uploadFolder = this.$store.getters["client/storeUploadFolder"] || this.$store.getters["user/storeUserConfig"]?.defaultUploadFolder || "";
    // 公告阅读记录
    const visitedTime = localStorage.getItem("announcementVisitedTime");
    const announcement = this.storeUserConfig?.announcement;
    const announcementTime = this.storeUserConfig?.announcementTime;
    if (announcement && announcementTime && (!visitedTime || visitedTime < announcementTime)) {
      this.announcementContent = announcement;
      this.showAnnouncementDialog = true;
    }
  },
  methods: {
    // 验证上传文件夹路径的合法性
    validateUploadFolder(path) {
      // 如果路径为空，返回true（允许空路径）
      if (!path || path.trim() === "") {
        return true;
      }
      // 检查路径是否以/开头
      if (!path.startsWith("/")) {
        this.$message.error('上传目录必须以 "/" 开头');
        return false;
      }
      // 检查路径是否包含非法字符
      const invalidChars = /[\\:\*\?"'<>\| \(\)\[\]\{\}#%\^`~;@&=\+\$,，]/;
      if (invalidChars.test(path)) {
        this.$message.error("上传目录包含非法字符，请使用合法的路径格式");
        return false;
      }
      // 检查路径是否包含连续的斜杠
      if (path.includes("//")) {
        this.$message.error("上传目录不能包含连续的斜杠");
        return false;
      }
      return true;
    },
    handleManage() {
      this.$router.push("/dashboard");
    },
    handleLogout() {
      cookies.remove("authCode");
      this.$router.push("/login");
      this.$message.success("已退出登录");
    },
    openSetting() {
      this.showSetting = true;
    },
    openGuide() {
      this.showGuide = true;
    },
    openAnnouncement() {
      this.announcementContent = this.storeUserConfig?.announcement || "";
      this.showAnnouncementDialog = true;
    },
    openToolbar() {
      this.isToolBarOpen = !this.isToolBarOpen;
      setTimeout(() => {
        const buttons = document.querySelectorAll(".toolbar-extend-button");
        buttons.forEach(button => {
          button.style.pointerEvents = this.isToolBarOpen ? "auto" : "none";
        });
      }, 300);
    },
    closeAnnouncement() {
      this.showAnnouncementDialog = false;
      const announcementTime = this.storeUserConfig?.announcementTime;
      if (announcementTime) {
        localStorage.setItem("announcementVisitedTime", announcementTime);
      }
    },
    // 移动端菜单处理
    handleMobileMenu(command) {
      switch (command) {
        case "theme":
          this.$refs.toggleDarkRef.handleToggleClick();
          break;
        case "guide":
          this.openGuide();
          break;
        case "announcement":
          this.openAnnouncement();
          break;
      }
    }
  }
};